namespace bgiplayer {
void SoundSubsystem::start_effect_playback(
    uint32_t channel, uint32_t volume, uint32_t pan) {
    if (check_effect(channel) != kOk) return;
    auto& slot = effect_channels_[channel];
    // 004C2850 / 1401165A0: stop/rewind, replace the play gain and
    // cancel the old silence envelope before starting this same media.
    slot.position = 0;
    slot.volume_level = std::min(volume, 0x80U);
    slot.pan = std::min(pan, 0x80U);
    slot.silence_fade = {};
    slot.full_level = 0x80U;
    slot.control_value = true;
    ++slot.effect_play_generation;
}
}  // namespace bgiplayer
